(() => {
  const escapeHTML = (value) => String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#39;");

  const lower = (value) => String(value ?? "").toLowerCase();

  const toDirection = (evt) => {
    const raw = lower(evt.direction || evt.phase || evt.kind);
    if (raw) return raw;
    const type = lower(evt.type || evt.event);
    if (type.includes("request")) return "request";
    if (type.includes("response")) return "response";
    if (type.includes("local")) return "local";
    return "event";
  };

  const toSummary = (evt) => {
    if (evt.summary) return String(evt.summary);
    if (evt.message) return String(evt.message);
    const data = evt.data || evt.payload || {};
    const parts = [];
    if (evt.method || data.method) parts.push(evt.method || data.method);
    if (evt.path || data.path) parts.push(evt.path || data.path);
    if (evt.note || data.note) parts.push(evt.note || data.note);
    if (parts.length > 0) return parts.join(" ");
    return JSON.stringify(data);
  };

  const toStatus = (evt) => String(evt.status || (evt.data && evt.data.status) || "");
  const toProvider = (evt) => String(evt.provider || evt.route || "");
  const toEvent = (evt) => String(evt.type || evt.event || "");
  const toTraceID = (evt) => String(evt.trace_id || evt.traceId || evt.traceID || "");
  const toTime = (evt) => {
    const raw = evt.ts || evt.time || evt.timestamp;
    if (!raw) return "";
    const date = new Date(raw);
    if (Number.isNaN(date.getTime())) return String(raw);
    return date.toLocaleTimeString();
  };

  const renderRow = (evt) => {
    const provider = toProvider(evt);
    const direction = toDirection(evt);
    const event = toEvent(evt);
    const status = toStatus(evt);
    const traceID = toTraceID(evt);
    const summary = toSummary(evt);
    const search = lower([provider, direction, event, traceID, summary].join(" "));
    const errorClass = String(status).startsWith("5") || lower(event).includes("error") ? " bg-destructive/5" : "";
    return `<tr data-provider="${escapeHTML(provider)}" data-event="${escapeHTML(event)}" data-direction="${escapeHTML(direction)}" data-search="${escapeHTML(search)}" class="border-b border-border align-top hover:bg-muted/40${errorClass}">`
      + `<td class="whitespace-nowrap px-4 py-3 text-xs text-muted-foreground">${escapeHTML(toTime(evt))}</td>`
      + `<td class="px-4 py-3">${escapeHTML(provider)}</td>`
      + `<td class="px-4 py-3"><span class="inline-flex rounded-full border border-border bg-background px-2 py-0.5 text-xs">${escapeHTML(direction)}</span></td>`
      + `<td class="px-4 py-3">${escapeHTML(event)}</td>`
      + `<td class="px-4 py-3">${escapeHTML(status)}</td>`
      + `<td class="px-4 py-3 font-mono text-xs text-muted-foreground">${escapeHTML(traceID)}</td>`
      + `<td class="px-4 py-3 text-sm">${escapeHTML(summary)}</td>`
      + `</tr>`;
  };

  const applyFilters = (root) => {
    const search = lower(root.querySelector('[data-tui-trafficstream-search]')?.value || "");
    const provider = root.querySelector('[data-tui-trafficstream-provider]')?.value || "";
    const event = root.querySelector('[data-tui-trafficstream-event]')?.value || "";
    const direction = root.querySelector('[data-tui-trafficstream-direction]')?.value || "";
    const rows = root.querySelectorAll('[data-tui-trafficstream-rows] tr');
    let visible = 0;
    rows.forEach((row) => {
      const matches = (!search || row.dataset.search.includes(search))
        && (!provider || row.dataset.provider === provider)
        && (!event || row.dataset.event === event)
        && (!direction || row.dataset.direction === direction);
      row.classList.toggle('hidden', !matches);
      if (matches) visible += 1;
    });
    const empty = root.querySelector('[data-tui-trafficstream-empty]');
    if (empty) empty.classList.toggle('hidden', visible > 0);
  };

  const updateConnection = (root, text, colorClass) => {
    const node = root.querySelector('[data-tui-trafficstream-connection]');
    if (!node) return;
    const dot = node.querySelector('span');
    if (dot) dot.className = `size-2 rounded-full ${colorClass}`;
    node.lastChild.textContent = ` ${text}`;
  };

  const init = (root) => {
    if (root.dataset.tuiTrafficstreamReady === 'true') return;
    root.dataset.tuiTrafficstreamReady = 'true';

    const rows = root.querySelector('[data-tui-trafficstream-rows]');
    const maxItems = Number(root.dataset.tuiTrafficstreamMaxItems || 250);
    let paused = false;
    let source = null;

    const trimRows = () => {
      while (rows && rows.children.length > maxItems) {
        rows.removeChild(rows.lastElementChild);
      }
    };

    const appendEvent = (evt) => {
      if (!rows || paused) return;
      rows.insertAdjacentHTML('afterbegin', renderRow(evt));
      trimRows();
      applyFilters(root);
    };

    root.querySelector('[data-tui-trafficstream-toggle]')?.addEventListener('click', (event) => {
      paused = !paused;
      event.currentTarget.textContent = paused ? 'Resume' : 'Pause';
      updateConnection(root, paused ? 'Paused' : 'Live', paused ? 'bg-warning' : 'bg-success');
    });

    root.querySelector('[data-tui-trafficstream-clear]')?.addEventListener('click', () => {
      if (rows) rows.innerHTML = '';
      applyFilters(root);
    });

    ['search', 'provider', 'event', 'direction'].forEach((name) => {
      root.querySelector(`[data-tui-trafficstream-${name}]`)?.addEventListener('input', () => applyFilters(root));
      root.querySelector(`[data-tui-trafficstream-${name}]`)?.addEventListener('change', () => applyFilters(root));
    });

    const streamURL = root.dataset.tuiTrafficstreamUrl;
    if (streamURL && typeof window.EventSource !== 'undefined') {
      source = new window.EventSource(streamURL);
      updateConnection(root, 'Live', 'bg-success');
      source.onmessage = (message) => {
        try {
          appendEvent(JSON.parse(message.data));
        } catch (_) {}
      };
      source.onerror = () => updateConnection(root, 'Reconnecting', 'bg-warning');
      // EventSource reconnects on its own after an error; open fires again
      // when it succeeds, so the badge goes back to the state it had.
      source.onopen = () => updateConnection(root, paused ? 'Paused' : 'Live', paused ? 'bg-warning' : 'bg-success');
    } else {
      updateConnection(root, 'Static', 'bg-muted-foreground');
    }

    applyFilters(root);
  };

  const boot = () => document.querySelectorAll('[data-tui-trafficstream]').forEach(init);
  document.addEventListener('DOMContentLoaded', boot);
  document.addEventListener('htmx:afterSwap', boot);
})();
